BEGIN;
CREATE TABLE IF NOT EXISTS public.sylaj_complete_records (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,module text NOT NULL CHECK(module IN ('leave','deadlines','payroll','plan','billing','materials','rates')),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),team_id text,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.sylaj_complete_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,module text NOT NULL,record_id bigint NOT NULL,actor uuid,operation text NOT NULL,old_data jsonb,new_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.sylaj_complete_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sylaj_complete_audit ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.sylaj_complete_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.profili WHERE id=auth.uid() AND vloga IN ('admin','administrator','skrbnik')) $$;
REVOKE ALL ON FUNCTION public.sylaj_complete_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.sylaj_complete_admin() TO authenticated;
REVOKE ALL ON public.sylaj_complete_records,public.sylaj_complete_audit FROM anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.sylaj_complete_records TO authenticated;
GRANT SELECT ON public.sylaj_complete_audit TO authenticated;
DROP POLICY IF EXISTS complete_admin ON public.sylaj_complete_records;
CREATE POLICY complete_admin ON public.sylaj_complete_records FOR ALL TO authenticated USING(public.sylaj_complete_admin()) WITH CHECK(public.sylaj_complete_admin());
DROP POLICY IF EXISTS complete_plan ON public.sylaj_complete_records;
CREATE POLICY complete_plan ON public.sylaj_complete_records FOR SELECT TO authenticated USING(module='plan' AND deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.ekipe e WHERE e.id::text=team_id AND e.vodja_id=auth.uid()));
DROP POLICY IF EXISTS complete_audit ON public.sylaj_complete_audit;
CREATE POLICY complete_audit ON public.sylaj_complete_audit FOR SELECT TO authenticated USING(public.sylaj_complete_admin());
CREATE OR REPLACE FUNCTION public.sylaj_complete_log() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.sylaj_complete_audit(module,record_id,actor,operation,old_data,new_data) VALUES(NEW.module,NEW.id,auth.uid(),TG_OP,CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS complete_log ON public.sylaj_complete_records;
CREATE TRIGGER complete_log AFTER INSERT OR UPDATE ON public.sylaj_complete_records FOR EACH ROW EXECUTE FUNCTION public.sylaj_complete_log();
CREATE UNIQUE INDEX IF NOT EXISTS complete_rates_unique ON public.sylaj_complete_records ((payload->>'key')) WHERE module='rates' AND deleted_at IS NULL;
COMMIT;
